/**
 * QR 参照矩阵快照（**由 Python `qrcode` 库生成后冻结**，⛔ 不要手改）。
 *
 * 用途：`tests/qrcode.test.ts` 拿它跟 `src/pure/qrcode.ts` 的产出**逐格比对**。
 * 二维码画错一格手机就扫不出，所以这里必须是「同文本 + 同版本 + 同纠错档 + 同掩码
 * ⇒ 矩阵一模一样」，⛔ 不能退化成「长得像」或「能画出来」这种弱断言。
 *
 * 重新生成的口径（Python 3 + `pip install qrcode`）：
 *   q = qrcode.QRCode(error_correction=<EC>, border=0, mask_pattern=<0..7>)
 *   q.add_data(qrcode.util.QRData(text.encode("utf-8"), mode=qrcode.util.MODE_8BIT_BYTE))
 *   q.make(fit=True); q.get_matrix()
 * 🔴 必须显式 `MODE_8BIT_BYTE`：`add_data(text)` 会自动把纯数字串切成 numeric 模式，
 *    版本与矩阵都不同（本仓编码器只有 byte 模式），那样比出来的「不一致」是假的。
 * 🔴 `border=0`：矩阵要的是纯模块区，带静默区就对不齐。
 */

import type { QrEcLevel } from '../../src/pure/qrcode';

export interface QrRef {
    version: number;
    /** 掩码 0–7 ⇒ 该掩码下的完整矩阵（每行一个 `1010…` 字符串） */
    masks: Record<number, readonly string[]>;
}

